# frozen_string_literal: true

module PhComposer
  module Assemblies
    module Assembly
      # Layer order is authored; orientation states which end is outside. Nested identities are
      # durable through edits and regenerated by Duplicate. Lengths are canonical millimetres.
      module Schema
        TYPES = %w[Wall RoofCeiling Floor].freeze
        CONDITIONS = %w[Outdoors Ground AttachedZone Adiabatic].freeze
        ORIENTATIONS = %w[first_layer_outside last_layer_outside].freeze
        SEGMENT = SchemaShapes.object({
          "id" => { "type" => "string" }, "width_mm" => SchemaFields.number("mm"),
          "material_id" => { "type" => %w[string null] },
          "is_continuous_insulation" => { "type" => "boolean" },
          "steel_stud_spacing_mm" => SchemaFields.number("mm", :nullable => true)
        })
        LAYER = SchemaShapes.object({
          "id" => { "type" => "string" }, "thickness_mm" => SchemaFields.number("mm"),
          "segments" => { "type" => "array", "minItems" => 1, "items" => SEGMENT }
        })
        LAYERS = { "type" => "array", "minItems" => 1, "items" => LAYER }.freeze
        AIR_BARRIER = SchemaShapes.object({
          "layer_id" => { "type" => "string" },
          "face" => { "type" => "string", "enum" => %w[interior exterior] }
        }).merge("type" => %w[object null])
        RAMP = %w[#a8c9ad #a5c5d7 #d5bea3 #cab6d4 #d5b1ad #b8c9cd].freeze

        module_function

        def segment(width_mm = 1000.0, identity: Records::Identity.method(:mint))
          { "id" => identity.call("seg"), "width_mm" => width_mm,
            "material_id" => nil, "is_continuous_insulation" => false, "steel_stud_spacing_mm" => nil }
        end

        def layer(thickness_mm = 100.0, identity: Records::Identity.method(:mint))
          { "id" => identity.call("lyr"), "thickness_mm" => thickness_mm,
            "segments" => [segment(1000.0, :identity => identity)] }
        end

        def defaults(values, identity: Records::Identity.method(:mint))
          { "orientation" => "first_layer_outside", "ventilated_cladding" => false,
            "layers" => [layer(100.0, :identity => identity)], "air_barrier" => nil, "photo_collections" => {} }
            .merge(SchemaFields.defaults(values))
        end

        def color(id)
          RAMP.fetch(id.each_byte.sum % RAMP.length)
        end

        def problems(values)
          found = SchemaFields.problems(values) + SchemaFields.source_problems(values["source"], SNAPSHOT_SCHEMA)
          layers = values.fetch("layers")
          layer_ids = layers.map { |entry| entry.fetch("id") }
          found << "Layer ids must be unique." unless layer_ids.uniq.length == layers.length
          layers.each { |entry| found.concat(layer_problems(entry)) }
          barrier = values["air_barrier"]
          if barrier && !layers.any? { |entry| entry.fetch("id") == barrier.fetch("layer_id") }
            found << "Air barrier Layer was not found."
          end
          found
        end

        def layer_problems(layer)
          found = []
          found << "Layer id is invalid." unless Records::Identity.pattern("lyr").match?(layer.fetch("id"))
          segments = layer.fetch("segments")
          unless segments.map { |entry| entry.fetch("id") }.uniq.length == segments.length
            found << "Layer-Segment ids must be unique within their Layer."
          end
          if segments.count { |entry| !entry["steel_stud_spacing_mm"].nil? } > 1
            found << "A Layer can carry only one steel stud spacing."
          end
          segments.each do |entry|
            found << "Layer-Segment id is invalid." unless Records::Identity.pattern("seg").match?(entry.fetch("id"))
            material_id = entry["material_id"]
            if material_id && !Records::Identity.pattern("mat").match?(material_id)
              found << "Material id is invalid."
            end
          end
          found
        end

        FIELDS = SchemaFields.common + [
          SchemaFields.field("type", { "type" => "string", "enum" => TYPES }),
          SchemaFields.field("orientation", { "type" => "string", "enum" => ORIENTATIONS }, :required => true),
          SchemaFields.field("exterior_condition", { "type" => "string", "enum" => CONDITIONS }),
          SchemaFields.field("ventilated_cladding", { "type" => "boolean" }),
          SchemaFields.field("color", { "type" => "string" }),
          SchemaFields.field("layers", LAYERS, :required => true),
          SchemaFields.field("air_barrier", AIR_BARRIER),
          SchemaFields.field("photo_collections", { "type" => "object" })
        ]
        SNAPSHOT_SCHEMA = SchemaFields.source_snapshot_schema(FIELDS)
        FIELDS.find { |field| field.key == "source" }.schema.fetch("properties")["snapshot"] = SNAPSHOT_SCHEMA

        # Every Layer-Segment's Material.
        MATERIAL_REFERENCE = Records::Reference.new(:key => "layers[].segments[].material_id",
                                                    :target_kind => MATERIAL_KIND, :cardinality => "one")

        KIND = Records::RecordKind.new(
          :id => ASSEMBLY_KIND, :label => "Assembly", :schema_version => 1, :id_prefix => "asm",
          :fields => FIELDS, :references => [MATERIAL_REFERENCE],
          :validate => method(:problems)
        )
      end
    end
  end
end
